mapper.select:
SELECT GROUP_ID, OWNER_ID, AMOUNT, MONTHS, STATUS
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{memberId}
AND STATUS    = 'ACTIVE'

SELECT COUNT(*)
FROM PAYMENT_PROOF
WHERE GROUP_ID  = #{groupId}
AND MEMBER_ID = #{memberId}
AND PAY_MONTH = #{payMonth}
AND ROUND_NO  = #{roundNo}

SELECT COUNT(*)
FROM PAYMENT_PROOF_FILE
WHERE FILE_HASH = #{fileHash}

mapper.insert:

    SELECT SEQ_PAYMENT_PROOF_FILE.NEXTVAL FROM DUAL

INSERT INTO PAYMENT_PROOF_FILE (
FILE_ID, PAYMENT_PROOF_ID, SORT_NO, FILE_PATH, ORIGIN_NAME,
MIME_TYPE, FILE_SIZE, FILE_HASH, ENCRYPTED_YN, KEY_VER
) VALUES (
#{fileId}, #{paymentProofId}, #{sortNo}, #{filePath}, #{originName},
#{mimeType}, #{fileSize}, #{fileHash}, #{encryptedYn}, #{keyVer}
)
